set -euo pipefail
finalize_outputs() {
python - <<'FINALIZE'
import hashlib,json,os,shutil,tarfile
from pathlib import Path
out=Path(os.environ['CQ_OUTPUT_DIR'])
# Pure eigensolver caches are regenerable from preserved graph inputs and pinned code.
for parent in (out/'ebcache',out/'work'/'eb_cache'):
    if parent.exists():
        for directory in list(parent.rglob('spectrum')):
            if directory.is_dir(): shutil.rmtree(directory)
# Preserve exact prepared inputs in a nested compressed archive to respect CQ's
# 500 MiB expanded outer archive ceiling; keep models, scores and logs unchanged.
tab=out/'work'/'tabular'
if tab.exists():
    results=out/'results';results.mkdir(exist_ok=True)
    if (tab/'cache_files_sha256.json').exists():
        shutil.copyfile(tab/'cache_files_sha256.json',results/'input_cache_files_sha256.json')
    archive=out/'prepared_tabular_inputs.tar.gz'
    with tarfile.open(archive,'w:gz') as tf:tf.add(tab,arcname='tabular',recursive=True)
    digest=hashlib.sha256(archive.read_bytes()).hexdigest()
    (results/'input_archive.json').write_text(json.dumps(dict(file=archive.name,sha256=digest,bytes=archive.stat().st_size)))
    shutil.rmtree(tab)
cache=out/'pip-cache'
if cache.exists():shutil.rmtree(cache)
files=[p for p in out.rglob('*') if p.is_file()]
for diagnostic in ('tests.txt','progress.log','financial_smoke/failures.json'):
    file=out/diagnostic
    if file.exists(): print('DIAGNOSTIC '+diagnostic+'\n'+file.read_text(errors='replace')[-16000:],flush=True)
print('OUTPUT_BYTES',sum(p.stat().st_size for p in files),flush=True)
FINALIZE
}
trap finalize_outputs EXIT
bash scripts/run_zero_label_cq.sh full
